package com.example.dsatracker.service;import com.example.dsatracker.dto.TagRequestDTO;import com.example.dsatracker.dto.TagResponseDTO;import com.example.dsatracker.exception.DuplicateResourceException;import com.example.dsatracker.exception.ResourceNotFoundException;import com.example.dsatracker.mapper.TagMapper;import com.example.dsatracker.model.Tag;import com.example.dsatracker.repository.TagRepository;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class TagService {    private final TagRepository repository;    public TagService(TagRepository repository) {        this.repository = repository;    }    public TagResponseDTO createTag(TagRequestDTO request) {        if (repository.existsByName(request.getName())) {            throw new DuplicateResourceException("Tag already exists.");        }        Tag tag = TagMapper.toEntity(request);        Tag savedTag = repository.save(tag);        return TagMapper.toResponse(savedTag);    }    public List<TagResponseDTO> getAllTags() {        return repository.findAll()                .stream()                .map(TagMapper::toResponse)                .toList();    }    public TagResponseDTO getTagById(Long id) {        Tag tag = repository.findById(id)                .orElseThrow(() ->                        new ResourceNotFoundException("Tag not found."));        return TagMapper.toResponse(tag);    }}